# 10-arapca-14 görsel modülü

GORSELLER = {'b1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">SAĞLIĞIM: VÜCUDUN ORGANLARI VE BEŞ DUYU (صِحَّتِي وَالْحَوَاسُّ الْخَمْسُ)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#2563eb">VÜCUDUN ORGANLARI (أَعْضَاءُ الْجِسْمِ)</text>\n  <text x="34" y="88" font-size="11" fill="#1e3a8a">• رَأْسٌ (Baş) · عَيْنٌ (Göz) · أُذُنٌ (Kulak)</text>\n  <text x="34" y="112" font-size="11" fill="#1e3a8a">• أَنْفٌ (Burun) · فَمٌ (Ağız) · أَسْنَانٌ (Dişler)</text>\n  <text x="34" y="136" font-size="11" fill="#1e3a8a">• يَدٌ (El) · رِجْلٌ / قَدَمٌ (Bacak / Ayak)</text>\n  <text x="34" y="160" font-size="11" fill="#1e3a8a">• مَعِدَةٌ / بَطْنٌ (Mide / Karın) · ظَهْرٌ (Sırt)</text>\n  <text x="34" y="184" font-size="11" fill="#1e3a8a">• قَلْبٌ (Kalp) · حَلْقٌ / حُنْجُرَةٌ (Boğaz)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#059669">BEŞ DUYU VE İŞLEVLERİ (الْحَوَاسُّ الْخَمْسُ)</text>\n  <text x="370" y="88" font-size="11" fill="#064e3b">• أَرَى بِالْعَيْنِ : Göz ile görürüm</text>\n  <text x="370" y="112" font-size="11" fill="#064e3b">• أَسْمَعُ بِالْأُذُنِ : Kulak ile işitirim</text>\n  <text x="370" y="136" font-size="11" fill="#064e3b">• أَشُمُّ بِالْأَنْفِ : Burun ile koklarım</text>\n  <text x="370" y="160" font-size="11" fill="#064e3b">• أَتَذَوَّقُ بِاللِّسَانِ : Dil ile tadarım</text>\n  <text x="370" y="184" font-size="11" fill="#064e3b">• أَلْمِسُ بِالْيَدِ : El ile dokunurum</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Bedenin çift organları (عَيْنٌ، أُذُنٌ، يَدٌ، رِجْلٌ) Arapçada semâî müennes kabul edilir.</text>\n</svg>', '1': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">SAĞLIĞIM: VÜCUDUN ORGANLARI VE BEŞ DUYU (صِحَّتِي وَالْحَوَاسُّ الْخَمْسُ)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#2563eb">VÜCUDUN ORGANLARI (أَعْضَاءُ الْجِسْمِ)</text>\n  <text x="34" y="88" font-size="11" fill="#1e3a8a">• رَأْسٌ (Baş) · عَيْنٌ (Göz) · أُذُنٌ (Kulak)</text>\n  <text x="34" y="112" font-size="11" fill="#1e3a8a">• أَنْفٌ (Burun) · فَمٌ (Ağız) · أَسْنَانٌ (Dişler)</text>\n  <text x="34" y="136" font-size="11" fill="#1e3a8a">• يَدٌ (El) · رِجْلٌ / قَدَمٌ (Bacak / Ayak)</text>\n  <text x="34" y="160" font-size="11" fill="#1e3a8a">• مَعِدَةٌ / بَطْنٌ (Mide / Karın) · ظَهْرٌ (Sırt)</text>\n  <text x="34" y="184" font-size="11" fill="#1e3a8a">• قَلْبٌ (Kalp) · حَلْقٌ / حُنْجُرَةٌ (Boğaz)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#059669">BEŞ DUYU VE İŞLEVLERİ (الْحَوَاسُّ الْخَمْسُ)</text>\n  <text x="370" y="88" font-size="11" fill="#064e3b">• أَرَى بِالْعَيْنِ : Göz ile görürüm</text>\n  <text x="370" y="112" font-size="11" fill="#064e3b">• أَسْمَعُ بِالْأُذُنِ : Kulak ile işitirim</text>\n  <text x="370" y="136" font-size="11" fill="#064e3b">• أَشُمُّ بِالْأَنْفِ : Burun ile koklarım</text>\n  <text x="370" y="160" font-size="11" fill="#064e3b">• أَتَذَوَّقُ بِاللِّسَانِ : Dil ile tadarım</text>\n  <text x="370" y="184" font-size="11" fill="#064e3b">• أَلْمِسُ بِالْيَدِ : El ile dokunurum</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Bedenin çift organları (عَيْنٌ، أُذُنٌ، يَدٌ، رِجْلٌ) Arapçada semâî müennes kabul edilir.</text>\n</svg>', 'b2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">HASTALIK ŞİKÂYETLERİ VE MUAYENE KALIPLARI (الْأَمْرَاضُ وَالْفَحْصُ)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">TEMEL HASTALIKLAR (الْأَمْرَاضُ الشَّائِعَةُ)</text>\n  <text x="34" y="88" font-size="11" fill="#7f1d1d">• صُدَاعٌ شَدِيدٌ : Şiddetli baş ağrısı</text>\n  <text x="34" y="112" font-size="11" fill="#7f1d1d">• نَزْلَةٌ / زُكَامٌ : Soğuk algınlığı / Nezle</text>\n  <text x="34" y="136" font-size="11" fill="#7f1d1d">• كُحَّةٌ / سُعَالٌ : Öksürük</text>\n  <text x="34" y="160" font-size="11" fill="#7f1d1d">• مَغْصٌ فِي الْبَطْنِ : Karın sancısı</text>\n  <text x="34" y="184" font-size="11" fill="#7f1d1d">• ضَغْطٌ مُرْتَفِعٌ / مُنْخَفِضٌ : Yüksek / Düşük tansiyon</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#2563eb">ŞİKÂYET BİLDİRME (التَّعْبِيرُ عَنِ الْأَلَمِ)</text>\n  <text x="370" y="88" font-size="11" fill="#1e3a8a">• بِمَ تَشْعُرُ؟ : Ne hissediyorsun? (Şikâyetin ne?)</text>\n  <text x="370" y="112" font-size="11" fill="#1e3a8a">• مِمَّ تَشْكُو؟ : Neden şikâyetçisin?</text>\n  <text x="370" y="136" font-size="11" fill="#1e3a8a">• أَشْعُرُ بِأَلَمٍ فِي رَأْسِي : Başımda ağrı hissediyorum</text>\n  <text x="370" y="160" font-size="11" fill="#1e3a8a">• عِنْدِي حُمَّى وَكُحَّةٌ : Ateşim ve öksürüğüm var</text>\n  <text x="370" y="184" font-size="11" fill="#1e3a8a">• يُؤْلِمُنِي سِنِّي : Dişim ağrıyor</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">أَشْعُرُ fiili بِـ harf-i ceriyle (أَشْعُرُ بِأَلَمٍ), أَشْكُو fiili ise مِنْ harf-i ceriyle kullanılır.</text>\n</svg>', '2': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">HASTALIK ŞİKÂYETLERİ VE MUAYENE KALIPLARI (الْأَمْرَاضُ وَالْفَحْصُ)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#dc2626">TEMEL HASTALIKLAR (الْأَمْرَاضُ الشَّائِعَةُ)</text>\n  <text x="34" y="88" font-size="11" fill="#7f1d1d">• صُدَاعٌ شَدِيدٌ : Şiddetli baş ağrısı</text>\n  <text x="34" y="112" font-size="11" fill="#7f1d1d">• نَزْلَةٌ / زُكَامٌ : Soğuk algınlığı / Nezle</text>\n  <text x="34" y="136" font-size="11" fill="#7f1d1d">• كُحَّةٌ / سُعَالٌ : Öksürük</text>\n  <text x="34" y="160" font-size="11" fill="#7f1d1d">• مَغْصٌ فِي الْبَطْنِ : Karın sancısı</text>\n  <text x="34" y="184" font-size="11" fill="#7f1d1d">• ضَغْطٌ مُرْتَفِعٌ / مُنْخَفِضٌ : Yüksek / Düşük tansiyon</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#2563eb">ŞİKÂYET BİLDİRME (التَّعْبِيرُ عَنِ الْأَلَمِ)</text>\n  <text x="370" y="88" font-size="11" fill="#1e3a8a">• بِمَ تَشْعُرُ؟ : Ne hissediyorsun? (Şikâyetin ne?)</text>\n  <text x="370" y="112" font-size="11" fill="#1e3a8a">• مِمَّ تَشْكُو؟ : Neden şikâyetçisin?</text>\n  <text x="370" y="136" font-size="11" fill="#1e3a8a">• أَشْعُرُ بِأَلَمٍ فِي رَأْسِي : Başımda ağrı hissediyorum</text>\n  <text x="370" y="160" font-size="11" fill="#1e3a8a">• عِنْدِي حُمَّى وَكُحَّةٌ : Ateşim ve öksürüğüm var</text>\n  <text x="370" y="184" font-size="11" fill="#1e3a8a">• يُؤْلِمُنِي سِنِّي : Dişim ağrıyor</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">أَشْعُرُ fiili بِـ harf-i ceriyle (أَشْعُرُ بِأَلَمٍ), أَشْكُو fiili ise مِنْ harf-i ceriyle kullanılır.</text>\n</svg>', 'b3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">HASTANE BÖLÜMLERİ, REÇETE VE İLAÇ KULLANIMI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#059669">SAĞLIK KURUMLARI (الْمُؤَسَّسَاتُ الصِّحِّيَّةُ)</text>\n  <text x="34" y="88" font-size="11" fill="#064e3b">• مُسْتَشْفَى : Hastane · عِيَادَةٌ : Poliklinik / Muayenehane</text>\n  <text x="34" y="112" font-size="11" fill="#064e3b">• صَيْدَلِيَّةٌ : Eczane · صَيْدَلِيٌّ : Eczacı</text>\n  <text x="34" y="136" font-size="11" fill="#064e3b">• طَبِيبٌ / طَبِيبَةٌ : Doktor · مُمَرِّضَةٌ : Hemşire</text>\n  <text x="34" y="160" font-size="11" fill="#064e3b">• فَحْصٌ طِبِّيٌّ : Tıbbi muayene</text>\n  <text x="34" y="184" font-size="11" fill="#064e3b">• وَصْفَةٌ طِبِّيَّةٌ : Reçete</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f5f3ff" stroke="#7c3aed" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#7c3aed">İLAÇ VE ZAMAN ZARFLARI (الدَّوَاءُ وَالظُّرُوفُ)</text>\n  <text x="370" y="88" font-size="11" fill="#4c1d95">• تَنَاوَلِ الدَّوَاءَ : İlacı al / kullan!</text>\n  <text x="370" y="112" font-size="11" fill="#4c1d95">• قَبْلَ الطَّعَامِ : Yemekten önce</text>\n  <text x="370" y="136" font-size="11" fill="#4c1d95">• بَعْدَ الطَّعَامِ : Yemekten sonra</text>\n  <text x="370" y="160" font-size="11" fill="#4c1d95">• مَرَّتَيْنِ فِي الْيَوْمِ : Günde iki defa</text>\n  <text x="370" y="184" font-size="11" fill="#4c1d95">• حَبَّةٌ / شَرَابٌ / مَرْهَمٌ : Hap / Şurup / Merhem</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Doktor reçeteye (وَصْفَةٌ طِبِّيَّةٌ) ilacın yemekten önce (قَبْلَ) veya sonra (بَعْدَ) alınacağını yazar.</text>\n</svg>', '3': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">HASTANE BÖLÜMLERİ, REÇETE VE İLAÇ KULLANIMI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#ecfdf5" stroke="#059669" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#059669">SAĞLIK KURUMLARI (الْمُؤَسَّسَاتُ الصِّحِّيَّةُ)</text>\n  <text x="34" y="88" font-size="11" fill="#064e3b">• مُسْتَشْفَى : Hastane · عِيَادَةٌ : Poliklinik / Muayenehane</text>\n  <text x="34" y="112" font-size="11" fill="#064e3b">• صَيْدَلِيَّةٌ : Eczane · صَيْدَلِيٌّ : Eczacı</text>\n  <text x="34" y="136" font-size="11" fill="#064e3b">• طَبِيبٌ / طَبِيبَةٌ : Doktor · مُمَرِّضَةٌ : Hemşire</text>\n  <text x="34" y="160" font-size="11" fill="#064e3b">• فَحْصٌ طِبِّيٌّ : Tıbbi muayene</text>\n  <text x="34" y="184" font-size="11" fill="#064e3b">• وَصْفَةٌ طِبِّيَّةٌ : Reçete</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f5f3ff" stroke="#7c3aed" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#7c3aed">İLAÇ VE ZAMAN ZARFLARI (الدَّوَاءُ وَالظُّرُوفُ)</text>\n  <text x="370" y="88" font-size="11" fill="#4c1d95">• تَنَاوَلِ الدَّوَاءَ : İlacı al / kullan!</text>\n  <text x="370" y="112" font-size="11" fill="#4c1d95">• قَبْلَ الطَّعَامِ : Yemekten önce</text>\n  <text x="370" y="136" font-size="11" fill="#4c1d95">• بَعْدَ الطَّعَامِ : Yemekten sonra</text>\n  <text x="370" y="160" font-size="11" fill="#4c1d95">• مَرَّتَيْنِ فِي الْيَوْمِ : Günde iki defa</text>\n  <text x="370" y="184" font-size="11" fill="#4c1d95">• حَبَّةٌ / شَرَابٌ / مَرْهَمٌ : Hap / Şurup / Merhem</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Doktor reçeteye (وَصْفَةٌ طِبِّيَّةٌ) ilacın yemekten önce (قَبْلَ) veya sonra (بَعْدَ) alınacağını yazar.</text>\n</svg>', 'b4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">HEDEF DİL YAPILARI: يَجِبُ أَنْ / يَنْبَغِي أَنْ / عَلَيْكَ أَنْ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#d97706">GEREKLİLİK KALIPLARI (أَسَالِيبُ الْوُجُوبِ)</text>\n  <text x="34" y="88" font-size="11" fill="#78350f">• يَجِبُ أَنْ تَسْتَرِيحَ : Dinlenmen gerekir</text>\n  <text x="34" y="112" font-size="11" fill="#78350f">• يَنْبَغِي أَنْ تَغْسِلَ يَدَيْكَ : Ellerini yıkamalısın</text>\n  <text x="34" y="136" font-size="11" fill="#78350f">• عَلَيْكَ أَنْ تَتَنَاوَلَ الدَّوَاءَ : İlacı alman gerekir</text>\n  <text x="34" y="160" font-size="11" fill="#78350f">• لَا تَأْكُلِ الْوَجَبَاتِ السَّرِيعَةَ : Fast food yeme!</text>\n  <text x="34" y="184" font-size="11" fill="#78350f">• اِشْرَبِ الْمَاءَ الْكَثِيرَ : Bol su iç!</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0f9ff" stroke="#0284c7" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#0284c7">أَنْ + MANSUB MUZÂRİ KURALLARI</text>\n  <text x="370" y="88" font-size="11" fill="#0c4a6e">• أَنْ edatı muzâri fiili nasbeder (sonunu fethalar)</text>\n  <text x="370" y="112" font-size="11" fill="#0c4a6e">• تَشْرَبُ (içiyorsun) -&gt; أَنْ تَشْرَبَ (içmen)</text>\n  <text x="370" y="136" font-size="11" fill="#0c4a6e">• تَنَامُ (uyuyorsun) -&gt; أَنْ تَنَامَ (uyuman)</text>\n  <text x="370" y="160" font-size="11" fill="#0c4a6e">• يُمَارِسُ (yapıyor) -&gt; أَنْ يُمَارِسَ (yapması)</text>\n  <text x="370" y="184" font-size="11" fill="#0c4a6e">• Açık mastar: يَجِبُ شُرْبُ الْمَاءِ (Su içmek gerekir)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">يَجِبُ أَنْ ve يَنْبَغِي أَنْ kalıplarından sonra gelen muzâri fiilin son harekesi fetha (-e/-a) olur.</text>\n</svg>', '4': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">HEDEF DİL YAPILARI: يَجِبُ أَنْ / يَنْبَغِي أَنْ / عَلَيْكَ أَنْ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#d97706">GEREKLİLİK KALIPLARI (أَسَالِيبُ الْوُجُوبِ)</text>\n  <text x="34" y="88" font-size="11" fill="#78350f">• يَجِبُ أَنْ تَسْتَرِيحَ : Dinlenmen gerekir</text>\n  <text x="34" y="112" font-size="11" fill="#78350f">• يَنْبَغِي أَنْ تَغْسِلَ يَدَيْكَ : Ellerini yıkamalısın</text>\n  <text x="34" y="136" font-size="11" fill="#78350f">• عَلَيْكَ أَنْ تَتَنَاوَلَ الدَّوَاءَ : İlacı alman gerekir</text>\n  <text x="34" y="160" font-size="11" fill="#78350f">• لَا تَأْكُلِ الْوَجَبَاتِ السَّرِيعَةَ : Fast food yeme!</text>\n  <text x="34" y="184" font-size="11" fill="#78350f">• اِشْرَبِ الْمَاءَ الْكَثِيرَ : Bol su iç!</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0f9ff" stroke="#0284c7" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#0284c7">أَنْ + MANSUB MUZÂRİ KURALLARI</text>\n  <text x="370" y="88" font-size="11" fill="#0c4a6e">• أَنْ edatı muzâri fiili nasbeder (sonunu fethalar)</text>\n  <text x="370" y="112" font-size="11" fill="#0c4a6e">• تَشْرَبُ (içiyorsun) -&gt; أَنْ تَشْرَبَ (içmen)</text>\n  <text x="370" y="136" font-size="11" fill="#0c4a6e">• تَنَامُ (uyuyorsun) -&gt; أَنْ تَنَامَ (uyuman)</text>\n  <text x="370" y="160" font-size="11" fill="#0c4a6e">• يُمَارِسُ (yapıyor) -&gt; أَنْ يُمَارِسَ (yapması)</text>\n  <text x="370" y="184" font-size="11" fill="#0c4a6e">• Açık mastar: يَجِبُ شُرْبُ الْمَاءِ (Su içmek gerekir)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">يَجِبُ أَنْ ve يَنْبَغِي أَنْ kalıplarından sonra gelen muzâri fiilin son harekesi fetha (-e/-a) olur.</text>\n</svg>', 'b5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">HEDEF SOSYAL İFADELER: GEÇMİŞ OLSUN VE ŞİFA DİLEKLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9333ea">HASTA ZİYARETİ İFADELERİ (عِبَارَاتُ عِيَادَةِ الْمَرِيضِ)</text>\n  <text x="34" y="88" font-size="11" fill="#581c87">• سَلَامَتُكَ / سَلَامَتُكِ : Geçmiş olsun! (Erkek / Kadın)</text>\n  <text x="34" y="112" font-size="11" fill="#581c87">• أَلْفُ سَلَامَةٍ عَلَيْكَ : Çok geçmiş olsun!</text>\n  <text x="34" y="136" font-size="11" fill="#581c87">• شَفَاكَ اللّٰهُ وَعَافَاكَ : Allah şifa ve afiyet versin!</text>\n  <text x="34" y="160" font-size="11" fill="#581c87">• لَا بَأْسَ طَهُورٌ إِنْ شَاءَ اللّٰهُ : Geçmiş olsun, şifa olsun</text>\n  <text x="34" y="184" font-size="11" fill="#581c87">• أَتَمَنَّى لَكَ الشِّفَاءَ الْعَاجِلَ : Acil şifalar dilerim</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#16a34a">MUAYENE VE TESELLİ İFADELERİ</text>\n  <text x="370" y="88" font-size="11" fill="#14532d">• لَا دَاعِيَ لِلْقَلَقِ : Endişeye gerek yok</text>\n  <text x="370" y="112" font-size="11" fill="#14532d">• اَلْأَمْرُ بَسِيطٌ : Durum basit / önemli değil</text>\n  <text x="370" y="136" font-size="11" fill="#14532d">• كَيْفَ تَشْعُرُ الْآنَ؟ : Şimdi nasıl hissediyorsun?</text>\n  <text x="370" y="160" font-size="11" fill="#14532d">• أَنَا بِخَيْرٍ وَالْحَمْدُ لِلّٰهِ : İyiyim, Allah\'a hamdolsun</text>\n  <text x="370" y="184" font-size="11" fill="#14532d">• شُكْرًا يَا حَكِيمُ : Teşekkür ederim doktor</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Erkek muhataba سَلَامَتُكَ / شَفَاكَ اللّٰهُ, kadın muhataba سَلَامَتُكِ / شَفَاكِ اللّٰهُ denir.</text>\n</svg>', '5': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">HEDEF SOSYAL İFADELER: GEÇMİŞ OLSUN VE ŞİFA DİLEKLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#9333ea">HASTA ZİYARETİ İFADELERİ (عِبَارَاتُ عِيَادَةِ الْمَرِيضِ)</text>\n  <text x="34" y="88" font-size="11" fill="#581c87">• سَلَامَتُكَ / سَلَامَتُكِ : Geçmiş olsun! (Erkek / Kadın)</text>\n  <text x="34" y="112" font-size="11" fill="#581c87">• أَلْفُ سَلَامَةٍ عَلَيْكَ : Çok geçmiş olsun!</text>\n  <text x="34" y="136" font-size="11" fill="#581c87">• شَفَاكَ اللّٰهُ وَعَافَاكَ : Allah şifa ve afiyet versin!</text>\n  <text x="34" y="160" font-size="11" fill="#581c87">• لَا بَأْسَ طَهُورٌ إِنْ شَاءَ اللّٰهُ : Geçmiş olsun, şifa olsun</text>\n  <text x="34" y="184" font-size="11" fill="#581c87">• أَتَمَنَّى لَكَ الشِّفَاءَ الْعَاجِلَ : Acil şifalar dilerim</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#16a34a">MUAYENE VE TESELLİ İFADELERİ</text>\n  <text x="370" y="88" font-size="11" fill="#14532d">• لَا دَاعِيَ لِلْقَلَقِ : Endişeye gerek yok</text>\n  <text x="370" y="112" font-size="11" fill="#14532d">• اَلْأَمْرُ بَسِيطٌ : Durum basit / önemli değil</text>\n  <text x="370" y="136" font-size="11" fill="#14532d">• كَيْفَ تَشْعُرُ الْآنَ؟ : Şimdi nasıl hissediyorsun?</text>\n  <text x="370" y="160" font-size="11" fill="#14532d">• أَنَا بِخَيْرٍ وَالْحَمْدُ لِلّٰهِ : İyiyim, Allah\'a hamdolsun</text>\n  <text x="370" y="184" font-size="11" fill="#14532d">• شُكْرًا يَا حَكِيمُ : Teşekkür ederim doktor</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Erkek muhataba سَلَامَتُكَ / شَفَاكَ اللّٰهُ, kadın muhataba سَلَامَتُكِ / شَفَاكِ اللّٰهُ denir.</text>\n</svg>', 'b6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">AYET, HADİS VE VECİZ SÖZLERDE SAĞLIK VE BOŞ ZAMAN</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#f0fdfa" stroke="#0f766e" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f766e">HADİS-İ ŞERİFLER (الْأَحَادِيثُ النَّبَوِيَّةُ)</text>\n  <text x="34" y="88" font-size="11" fill="#134e4a">• اَلطُّهُورُ شَطْرُ الْإِيمَانِ : Temizlik imanın yarısıdır</text>\n  <text x="34" y="112" font-size="11" fill="#134e4a">• نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ :</text>\n  <text x="34" y="136" font-size="11" fill="#134e4a">• İki nimet vardır ki insanların çoğu kıymetini bilmez:</text>\n  <text x="34" y="160" font-size="11" fill="#134e4a">• اَلصِّحَّةُ وَالْفَرَاغُ : Sağlık ve boş vakit (Buhârî)</text>\n  <text x="34" y="184" font-size="11" fill="#134e4a">• تَدَاوَوْا عِبَادَ اللّٰهِ : Ey Allah\'ın kulları, tedavi olun!</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#b45309" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">VECİZ SÖZLER (الْحِكَمُ وَالْأَمْثَالُ)</text>\n  <text x="370" y="88" font-size="11" fill="#78350f">• اَلْعَقْلُ السَّلِيمُ فِي الْجِسْمِ السَّلِيمِ : Sağlam kafa sağlam vücutta</text>\n  <text x="370" y="112" font-size="11" fill="#78350f">• اَلْوِقَايَةُ خَيْرٌ مِنَ الْعِلَاجِ : Korunmak tedaviden hayırlıdır</text>\n  <text x="370" y="136" font-size="11" fill="#78350f">• اَلصِّحَّةُ تَاجٌ عَلَى رُؤُوسِ الْأَصِحَّاءِ : Sağlık tac gibidir</text>\n  <text x="370" y="160" font-size="11" fill="#78350f">• اَلنَّظَافَةُ مِنَ الْإِيمَانِ : Temizlik imandandır</text>\n  <text x="370" y="184" font-size="11" fill="#78350f">• اَلْوَقْتُ كَالسَّيْفِ : Vakit kılıç gibidir</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">İslam\'da beden sağlığını korumak (الْوِقَايَةُ) ve boş vakti faydalı hobilerle değerlendirmek esastır.</text>\n</svg>', '6': '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">AYET, HADİS VE VECİZ SÖZLERDE SAĞLIK VE BOŞ ZAMAN</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#f0fdfa" stroke="#0f766e" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f766e">HADİS-İ ŞERİFLER (الْأَحَادِيثُ النَّبَوِيَّةُ)</text>\n  <text x="34" y="88" font-size="11" fill="#134e4a">• اَلطُّهُورُ شَطْرُ الْإِيمَانِ : Temizlik imanın yarısıdır</text>\n  <text x="34" y="112" font-size="11" fill="#134e4a">• نِعْمَتَانِ مَغْبُونٌ فِيهِمَا كَثِيرٌ مِنَ النَّاسِ :</text>\n  <text x="34" y="136" font-size="11" fill="#134e4a">• İki nimet vardır ki insanların çoğu kıymetini bilmez:</text>\n  <text x="34" y="160" font-size="11" fill="#134e4a">• اَلصِّحَّةُ وَالْفَرَاغُ : Sağlık ve boş vakit (Buhârî)</text>\n  <text x="34" y="184" font-size="11" fill="#134e4a">• تَدَاوَوْا عِبَادَ اللّٰهِ : Ey Allah\'ın kulları, tedavi olun!</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#fef3c7" stroke="#b45309" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">VECİZ SÖZLER (الْحِكَمُ وَالْأَمْثَالُ)</text>\n  <text x="370" y="88" font-size="11" fill="#78350f">• اَلْعَقْلُ السَّلِيمُ فِي الْجِسْمِ السَّلِيمِ : Sağlam kafa sağlam vücutta</text>\n  <text x="370" y="112" font-size="11" fill="#78350f">• اَلْوِقَايَةُ خَيْرٌ مِنَ الْعِلَاجِ : Korunmak tedaviden hayırlıdır</text>\n  <text x="370" y="136" font-size="11" fill="#78350f">• اَلصِّحَّةُ تَاجٌ عَلَى رُؤُوسِ الْأَصِحَّاءِ : Sağlık tac gibidir</text>\n  <text x="370" y="160" font-size="11" fill="#78350f">• اَلنَّظَافَةُ مِنَ الْإِيمَانِ : Temizlik imandandır</text>\n  <text x="370" y="184" font-size="11" fill="#78350f">• اَلْوَقْتُ كَالسَّيْفِ : Vakit kılıç gibidir</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">İslam\'da beden sağlığını korumak (الْوِقَايَةُ) ve boş vakti faydalı hobilerle değerlendirmek esastır.</text>\n</svg>'}

def uygula(v):
    for idx, b in enumerate(v.get('bolumler', []), 1):
        svg = GORSELLER.get(f'b{idx}') or GORSELLER.get(str(idx))
        if svg:
            b['gorsel'] = svg
    return v
